#include "guardrails.hpp"
namespace g9 {
GuardrailDecision Guardrails::decide(const ActionDescriptor&a)const{if(a.risk==RiskClass::forbidden||a.risk==RiskClass::vcs_destructive)return{PolicyAction::deny,"hard-denied action"};PolicyAction b=PolicyAction::deny;switch(profile_){case GuardrailProfile::review:switch(a.risk){case RiskClass::read:case RiskClass::vcs_read:b=PolicyAction::allow;break;case RiskClass::write:case RiskClass::execute:case RiskClass::unsandboxed_execute:case RiskClass::vcs_write:b=PolicyAction::ask;break;default:b=PolicyAction::deny;}break;case GuardrailProfile::balanced:switch(a.risk){case RiskClass::read:case RiskClass::write:case RiskClass::execute:case RiskClass::vcs_read:b=PolicyAction::allow;break;case RiskClass::unsandboxed_execute:case RiskClass::filesystem_destructive:case RiskClass::vcs_write:b=PolicyAction::ask;break;default:b=PolicyAction::deny;}break;case GuardrailProfile::autonomous_mode:switch(a.risk){case RiskClass::read:case RiskClass::write:case RiskClass::execute:case RiskClass::vcs_read:case RiskClass::vcs_write:b=PolicyAction::allow;break;case RiskClass::unsandboxed_execute:case RiskClass::filesystem_destructive:b=PolicyAction::ask;break;default:b=PolicyAction::deny;}}
if(b==PolicyAction::ask&&!a.equivalence_key.empty()&&session_allows(a.equivalence_key))return{PolicyAction::allow,"allowed by session grant"};return{b,b==PolicyAction::allow?"allowed by policy":b==PolicyAction::ask?"approval required":"denied by policy"};}
std::string to_string(RiskClass r){switch(r){case RiskClass::read:return"read";case RiskClass::write:return"write";case RiskClass::execute:return"execute";case RiskClass::unsandboxed_execute:return"unsandboxed-execute";case RiskClass::filesystem_destructive:return"filesystem-destructive";case RiskClass::vcs_read:return"vcs-read";case RiskClass::vcs_write:return"vcs-write";case RiskClass::vcs_destructive:return"vcs-destructive";case RiskClass::forbidden:return"forbidden";}return"unknown";}
std::string to_string(GuardrailProfile p){switch(p){case GuardrailProfile::review:return"review";case GuardrailProfile::balanced:return"balanced";case GuardrailProfile::autonomous_mode:return"autonomous";}return"unknown";}
} // namespace g9
